                // Function to switch between tabs
                function switchTab(containerId, tabId) {
                    // Get all tab buttons in this container
                    const tabButtons = document.querySelectorAll('[data-tab-container="' + containerId + '"]');
                    
                    // Remove active class from all buttons
                    tabButtons.forEach(button => {
                        button.classList.remove('active');
                        button.style.borderBottom = '2px solid transparent';
                        button.style.color = '${n["status.disabled"]}';
                    });
                    
                    // Add active class to clicked button
                    const activeButton = document.querySelector('[data-tab-container="' + containerId + '"][data-tab-id="' + tabId + '"]');
                    if (activeButton) {
                        activeButton.classList.add('active');
                        activeButton.style.borderBottom = '2px solid ${n["status.enabled"]}';
                        activeButton.style.color = '${n["status.enabled"]}';
                    }
                    
                    // Handle tab panels visibility
                    const containerNum = containerId.split('-').pop();
                    const allPanels = document.querySelectorAll('[data-tab-panel^="tab-' + containerNum + '-"]');
                    allPanels.forEach(panel => {
                        panel.removeAttribute('data-tab-active');
                        panel.style.display = 'none';
                    });
                    
                    // Show the selected panel
                    const activePanel = document.querySelector('[data-tab-panel="' + tabId + '"]');
                    if (activePanel) {
                        activePanel.setAttribute('data-tab-active', 'true');
                        activePanel.style.display = 'block';
                    }
                    
                    // Update active tab in localStorage for persistence
                    const activeTabsData = JSON.parse(localStorage.getItem('activeTabsData') || '{}');
                    activeTabsData[containerId] = tabId;
                    localStorage.setItem('activeTabsData', JSON.stringify(activeTabsData));
                }
                
